  import { planLabel } from '$lib/product/navigation.js';
  import TodayAgenda from './TodayAgenda.svelte';
  let sport = 'nba';
  $: name = $currentUser?.displayName?.split(' ')[0];
  const sports = {
    nba: { title: 'Cada posesión cuenta.', label: 'BALONCESTO / NBA', text: 'Pon el ritmo, la anotación y el contexto de los equipos en el centro del análisis.', href: '/sports/nba', action: 'Entrar al centro NBA', features: ['Calendario de la jornada', 'Análisis de totales', 'Factores de cada equipo'] },
    tennis: { title: 'La superficie lo cambia todo.', label: 'TENIS / INDIVIDUALES', text: 'Compara jugadores, enfrenta su historial y descubre cómo cambia su rendimiento en cada pista.', href: '/tennis', action: 'Entrar a Tennis Lab', features: ['Hoy y mañana · masculino y femenino', 'Forma, superficies y cara a cara', 'Saque, resto y estado físico'] }
  };
  $: selected = sports[sport];
</script>

<div class="home">
  <section class="hero" aria-labelledby="home-title">
