        <div class="orbital" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="orb-core"><svg viewBox="0 0 120 120" fill="none"><path d="M28 88V32l32 23 32-23v56L60 65 28 88Z" fill="currentColor"/><path d="M60 55v10l32 23V32L60 55Z" fill="#6c7fe4"/></svg></div><span class="orbit-label label-a">01 / CONTEXTO</span><span class="orbit-label label-b">02 / ANÁLISIS</span><span class="orbit-label label-c">03 / CONTROL</span><span class="orbit-dot"></span></div>
