  .home-body{max-width:1280px;margin:auto;padding:28px 36px 70px}.section-top{display:flex;justify-content:space-between;align-items:end;gap:20px;margin:46px 0 22px}.section-top .eyebrow,.tools .eyebrow,.method .eyebrow{color:var(--muted)}h2{font-size:clamp(27px,3vw,37px);line-height:1.2;margin-top:12px}.sport-switch{display:flex;padding:5px;border:1px solid var(--line);border-radius:10px;background:var(--surface)}.sport-switch button{background:transparent;border:0;color:var(--muted);border-radius:6px;padding:11px 20px;font-size:14px;font-weight:650}.sport-switch button.active{background:#294d94;color:#fff}.sport-feature{display:grid;grid-template-columns:1fr 1.1fr;border:1px solid var(--line);border-radius:16px;overflow:hidden;background:var(--surface)}.sport-art{position:relative;min-height:340px;display:flex;align-items:end;padding:30px;background:radial-gradient(ellipse at 65% 30%,#97623c,#251c23 68%);overflow:hidden}.sport-art>span{position:relative;color:#f2ded0;font-size:44px;font-weight:800;line-height:.95;letter-spacing:-2px;z-index:1}.basketball{position:absolute;right:9%;top:9%;width:210px;aspect-ratio:1;border-radius:50%;background:radial-gradient(circle at 30% 20%,#d9a770,#ac683a 50%,#45251d);box-shadow:20px 30px 50px #0007,inset -10px -10px 30px #251417;overflow:hidden;transform:rotate(-22deg);border:2px solid #d6a07855;transition:transform .6s}.basketball:before,.basketball:after,.basketball i,.basketball b{content:'';position:absolute;border:2px solid #3e291e;border-radius:50%}.basketball:before{width:150%;height:40%;left:-25%;top:30%}.basketball:after{height:150%;width:40%;left:30%;top:-25%}.basketball i{left:50%;height:100%;border-radius:0}.basketball b{top:50%;width:100%;border-radius:0}.sport-feature:hover .basketball{transform:rotate(-12deg) translateY(-5px)}.sport-art img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.7}.tennis .sport-art{background:#10251b}.tennis .sport-art>span{color:#ddecbd}.sport-copy{padding:3